(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c2-basic-3"]={"id":"unit31-trap-c2-basic-3","unitId":"3-1","chapterIds":["3-1"],"unitType":"basic","group":"3-1단원 · 선지 변형 유형 · 인과","name":"기본 OX 3","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"인과","parts":[{"name":"U31-H11-01-B1 · 주는 기쁨","items":[{"paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 1/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 11문단","passage":"[핵심 문장 · 11문단]\n우리는 주는 데서 큰 기쁨을 맛본다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"주는 행위에서도 큰 기쁨을 맛본다.\n근거: “우리는 주는 데서 큰 기쁨을 맛본다.”","evidence":{"title":"주는 기쁨","statement":"사람은 주는 데서도 기쁨을 느낀다.","explanation":"주는 행위에서도 큰 기쁨을 맛본다.\n근거: “우리는 주는 데서 큰 기쁨을 맛본다.”","valid":["R11:3"],"sources":[{"id":"R11","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"11문단","sentences":[{"id":"R11:3","text":"우리는 주는 데서 큰 기쁨을 맛본다.","paragraph":0,"memberIds":["R11:3"],"topic":"우리는 줄 때 큰 기쁨을 맛본다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R11:3","text":"우리는 주는 데서 큰 기쁨을 맛본다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H11-01-B1","type":"ox","answer":"O","changed":"사람은 주는 데서도 기쁨을 느낀다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":1,"progressiveTotal":5,"progressiveLabel":"핵심 낱말과 사실","learningFocus":"주는 기쁨","hintGuide":"기쁨이 생기는 행동을 찾아보세요.","synthesis":false,"editorSourceVersion":"142754bb2bd7143592161cfd5403aca3151b2301956e228c4a480bc529af7430"}]},{"name":"U31-H11-04-B1 · 사랑을 준 사람이 느끼는 기쁨","items":[{"paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 4/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 11문단","passage":"[핵심 문장 · 11문단]\n이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다. 그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"사랑을 받아 기뻐하는 상대를 보면서 사랑을 준 사람도 기쁨과 보람을 얻는다.\n근거: “이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.” “그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.”","evidence":{"title":"사랑을 준 사람이 느끼는 기쁨","statement":"상대의 삶이 밝아지는 모습을 보면, 사랑을 준 사람도 마음이 풍성해진다.","explanation":"사랑을 받아 기뻐하는 상대를 보면서 사랑을 준 사람도 기쁨과 보람을 얻는다.\n근거: “이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.” “그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.”","valid":["R11:8","R11:9"],"sources":[{"id":"R11","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"11문단","sentences":[{"id":"R11:8","text":"이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.","paragraph":0,"memberIds":["R11:8"],"topic":"이렇게 주면서 우리는 다른 사람의 생명(삶)을 밝고 가득 차게(충만하게) 만든다."},{"id":"R11:9","text":"그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.","paragraph":0,"memberIds":["R11:9"],"topic":"그리고 다른 사람의 삶이 밝아지고 가득 차는 것을 보면서, 우리도 더 밝아지고 가득 차게 된다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R11:8","text":"이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다."},{"id":"R11:9","text":"그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H11-04-B1","type":"ox","answer":"O","changed":"상대의 삶이 밝아지는 모습을 보면, 사랑을 준 사람도 마음이 풍성해진다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"사랑을 준 사람이 느끼는 기쁨","hintGuide":"사랑을 받은 사람만 기쁜지 사랑을 준 사람도 기쁜지 보세요.","synthesis":false,"editorSourceVersion":"fa441c37e0be20cc7c34036c7b9bcfa13368c4a046626042bb719d31b13f48b8"}]},{"name":"U31-P12-04-B1 · 인과","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"극복하지 못하면 주기를 두려워한다.","statement":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.","explanation":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","valid":["R12:3"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"id":"U31-P12-04-B1","type":"ox","answer":"O","changed":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"editorSourceVersion":"822cce8f61f1267d37b8e7dd14c8a659597a158684212c2af89b38661b97d5b9"}]},{"name":"U31-P12-04-B2 · 인과","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"극복하지 못하면 주기를 두려워한다.","statement":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.","explanation":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","valid":["R12:3"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"id":"U31-P12-04-B2","type":"ox","answer":"X","changed":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못해도, 다른 사람에게 사랑을 주는 일을 두려워하지 않는다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"claimEdits":[{"start":27,"end":32,"before":"못해도, ","after":"못하면, "},{"start":50,"end":60,"before":"두려워하지 않는다.","after":"두려워한다."}],"editorSourceVersion":"64277e3b971ad0451566f015077514ca4215f2a81db929b1bddf9def780c9f6a"}]},{"name":"U31-H12-04-B2 · 남에게 기대는 마음을 이겨 내기","items":[{"paragraphCount":1,"readingLabel":"12문단 · 핵심 읽기 4/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[핵심 문장 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"남에게 의존하려는 태도를 넘어선 사람이 사랑을 줄 수 있다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.” “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”","evidence":{"title":"남에게 기대는 마음을 이겨 내기","statement":"사랑을 줄 수 있는 사람은 남에게 기대려는 마음을 이겨 내면서 성숙해진 사람이다.","explanation":"남에게 의존하려는 태도를 넘어선 사람이 사랑을 줄 수 있다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.” “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”","valid":["R12:1","R12:2"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H12-04-B2","type":"ox","answer":"X","changed":"사랑을 줄 수 있는 사람은 남에게 더 많이 기대면서 성숙해진 사람이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","claimEdits":[{"start":19,"end":29,"before":"더 많이 기대면서 ","after":"기대려는 마음을 이겨 내면서 "}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"남에게 기대는 마음을 이겨 내기","hintGuide":"성숙하려면 남에게 기대는 마음을 키워야 하는지 줄여야 하는지 보세요.","synthesis":false,"editorSourceVersion":"4c19cd50b29950dc6547c15f6a0e825b367d6439c4bea36cb57b33d8e524ba4d"}]},{"name":"U31-H13-04-B2 · 존경 없는 책임이 바뀌는 모습","items":[{"paragraphCount":1,"readingLabel":"13문단 · 핵심 읽기 4/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[핵심 문장 · 13문단]\n존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"상대의 개성을 존중하지 않은 채 책임지려 하면 상대를 내 뜻대로 하려는 욕심이 될 수 있다.\n근거: “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”","evidence":{"title":"존경 없는 책임이 바뀌는 모습","statement":"상대를 존경하지 않으면 책임은 상대를 지배하고 소유하려는 마음이 된다.","explanation":"상대의 개성을 존중하지 않은 채 책임지려 하면 상대를 내 뜻대로 하려는 욕심이 될 수 있다.\n근거: “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”","valid":["R13:9"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H13-04-B2","type":"ox","answer":"X","changed":"상대를 존경하지 않으면 책임은 상대의 개성을 지키려는 마음이 된다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","claimEdits":[{"start":17,"end":30,"before":"상대의 개성을 지키려는 ","after":"상대를 지배하고 소유하려는 "}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"존경 없는 책임이 바뀌는 모습","hintGuide":"존경이 없을 때 책임이 어떤 욕심으로 바뀌는지 보세요.","synthesis":false,"editorSourceVersion":"0f018444829b403adda259d824735b106b4a945923e98c3f057b7153bb6f4f2d"}]},{"name":"U31-H16-04-B1 · 어려움과 훈련","items":[{"paragraphCount":1,"readingLabel":"16문단 · 핵심 읽기 4/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 16문단","passage":"[핵심 문장 · 16문단]\n우리는 보통 사랑이 저절로 생긴다고 생각하지만, 프롬은 제대로 사랑하는 것이야말로 가장 어려운 것이며 끊임없는 노력과 훈련이 필요하다고 보았다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"프롬은 제대로 사랑하기가 어렵기 때문에 계속 노력하고 훈련해야 한다고 말한다.\n근거: “우리는 보통 사랑이 저절로 생긴다고 생각하지만, 프롬은 제대로 사랑하는 것이야말로 가장 어려운 것이며 끊임없는 노력과 훈련이 필요하다고 보았다.”","evidence":{"title":"어려움과 훈련","statement":"제대로 사랑하는 일이 어렵기 때문에 노력과 훈련이 요구된다.","explanation":"프롬은 제대로 사랑하기가 어렵기 때문에 계속 노력하고 훈련해야 한다고 말한다.\n근거: “우리는 보통 사랑이 저절로 생긴다고 생각하지만, 프롬은 제대로 사랑하는 것이야말로 가장 어려운 것이며 끊임없는 노력과 훈련이 필요하다고 보았다.”","valid":["R16:1"],"sources":[{"id":"R16","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"16문단","sentences":[{"id":"R16:1","text":"우리는 보통 사랑이 저절로 생긴다고 생각하지만, 프롬은 제대로 사랑하는 것이야말로 가장 어려운 것이며 끊임없는 노력과 훈련이 필요하다고 보았다.","paragraph":0,"memberIds":["R16:1"],"topic":"우리는 보통 사랑이 저절로 생긴다고 생각한다. 하지만 프롬은 제대로 사랑하는 것이야말로 가장 어려운 일이고, 끊임없는 노력과 훈련이 필요하다고 보았다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R16:1","text":"우리는 보통 사랑이 저절로 생긴다고 생각하지만, 프롬은 제대로 사랑하는 것이야말로 가장 어려운 것이며 끊임없는 노력과 훈련이 필요하다고 보았다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H16-04-B1","type":"ox","answer":"O","changed":"제대로 사랑하는 일이 어렵기 때문에 노력과 훈련이 요구된다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"어려움과 훈련","hintGuide":"사랑이 어렵다는 생각과 연습해야 한다는 생각이 어떻게 이어지는지 보세요.","synthesis":false,"editorSourceVersion":"1a73d937cfb4e2af92df192d3cec8ccfb2ae65cea616d5e3b75a406f80dbd2ab"}]}]};})(window);
